#include <set>

class material;

template <class T>
class instance_bank
{
public:
  struct ref_t
  {
    void *label;
    T *ptr;
    unsigned int count;
  };

  class less_by_ptr : public binary_function<const ref_t *, const ref_t *, bool>
  {
  public:
    bool operator()(const ref_t *a, const ref_t *b) const
    {
      return a->ptr < b->ptr;
    }
  };
};

typedef instance_bank<material>::ref_t material_ref_t;
typedef instance_bank<material>::less_by_ptr material_less_by_ptr_t;
typedef set<material_ref_t *, material_less_by_ptr_t, malloc_alloc> material_ref_set_t;

template pair<material_ref_set_t::iterator, bool>
material_ref_set_t::insert(material_ref_t *const &);
